--------------------------------------------------------------------------------
-- OGP.GEBAEUDE - 598 Gebaeude aus Overpass, Ausschnitt Niendorfer Hafen
-- Erzeugt aus dem GeoJSON-Export; Polygone in SRID 8307 (WGS 84).
--
-- Als OGP ausfuehren:  sqlplus OGP/ogp@//localhost:1521/PDBORCL @ogp_gebaeude_daten.sql
--
-- Zur Hoehe: OSM hat hier KEIN einziges height-Attribut, und nur 52 der 598
-- Gebaeude tragen building:levels. HEIGHT_M ist deshalb eine echte Spalte, kein
-- abgeleiteter Ausdruck, und HEIGHT_SOURCE sagt je Zeile, woher der Wert kommt:
--   OSM         - aus building:levels x 3 m, zuzueglich roof:levels x 2,5 m
--   SCHAETZUNG  - aus dem Gebaeudetyp (Schuppen 2,8 / Haus 6,5 / Wohnblock 11 ...)
-- Wer die Schaetzung nicht will, filtert in der Ansicht auf HEIGHT_SOURCE='OSM'.
--------------------------------------------------------------------------------
SET DEFINE OFF
SET SQLBLANKLINES ON

BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE GEBAEUDE CASCADE CONSTRAINTS PURGE';
EXCEPTION
  WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/

DELETE FROM user_sdo_geom_metadata WHERE table_name = 'GEBAEUDE';
COMMIT;

CREATE TABLE GEBAEUDE (
  ID            NUMBER GENERATED BY DEFAULT AS IDENTITY,
  OSM_ID        NUMBER,
  NAME          VARCHAR2(256),
  ART           VARCHAR2(64),
  LEVELS        NUMBER(4,1),
  ROOF_LEVELS   NUMBER(4,1),
  HEIGHT_M      NUMBER(6,2)   NOT NULL,
  HEIGHT_SOURCE VARCHAR2(12)  NOT NULL,
  GEOM          SDO_GEOMETRY,
  CONSTRAINT GEBAEUDE_PK PRIMARY KEY (ID),
  CONSTRAINT GEBAEUDE_HSRC_CK CHECK (HEIGHT_SOURCE IN ('OSM','SCHAETZUNG'))
);

COMMENT ON COLUMN GEBAEUDE.HEIGHT_M      IS 'Bauhoehe in Metern, von FExtrusionBuilder verwendet';
COMMENT ON COLUMN GEBAEUDE.HEIGHT_SOURCE IS 'OSM = aus Geschosszahl gerechnet, SCHAETZUNG = aus dem Gebaeudetyp';

