CREATE INDEX GEBAEUDE_GEOM_SX ON GEBAEUDE (GEOM) INDEXTYPE IS MDSYS.SPATIAL_INDEX_V2;

GRANT SELECT ON GEBAEUDE TO DEMO;

--------------------------------------------------------------------------------
-- Pruefen
--------------------------------------------------------------------------------
SELECT COUNT(*) AS GESAMT FROM GEBAEUDE;

SELECT HEIGHT_SOURCE, COUNT(*) ANZAHL, ROUND(MIN(HEIGHT_M),1) MIN_M,
       ROUND(AVG(HEIGHT_M),1) MITTEL_M, ROUND(MAX(HEIGHT_M),1) MAX_M
  FROM GEBAEUDE GROUP BY HEIGHT_SOURCE ORDER BY 2 DESC;

-- Alle Geometrien gueltig? Erwartet: 598 x TRUE
SELECT VALID, COUNT(*) FROM (
  SELECT SDO_GEOM.VALIDATE_GEOMETRY_WITH_CONTEXT(g.GEOM, 0.05) AS VALID FROM GEBAEUDE g
) GROUP BY VALID;

SELECT COUNT(*) AS IN_DER_KACHEL
  FROM GEBAEUDE g
 WHERE SDO_FILTER(g.GEOM,
         SDO_CS.TRANSFORM(
           SDO_GEOMETRY(2003, 25832, NULL, SDO_ELEM_INFO_ARRAY(1,1003,3),
             SDO_ORDINATE_ARRAY(618000.5, 5984000.5, 618995.5, 5984995.5)), 8307),
         'querytype=WINDOW') = 'TRUE';
